// Generated by scripts/build-release.mjs. Wait for old clients to close before activation.
const CACHE="teddy-shell-0.6.5+a2dfefc6db0f";
const FILES=["./","./index.html","./app.js","./core.js","./meal-plans.js","./feeding-review.js","./nutrient-guidance.js","./storage.js","./optimizer.js","./optimizer-worker.js","./vendor/yalps.js","./food-data.js","./food-reference.js","./food-estimates.js","./food-review.js","./style.css","./icon.svg","./icon-180.png","./icon-192.png","./icon-512.png","./manifest.webmanifest","./release.js"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES))));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
  for(const key of await caches.keys())if(key.startsWith('teddy-shell-') && key!==CACHE)await caches.delete(key);
  await self.clients.claim();
})()));
// Update now: activate only when this is the sole open window, so no older tab keeps running old code.
self.addEventListener('message',event=>{
  if(event.data!=='activate-if-alone')return;
  event.waitUntil(self.clients.matchAll({type:'window'}).then(windows=>{
    if(windows.length<=1){self.skipWaiting();event.source?.postMessage({update:'activating'});}
    else event.source?.postMessage({update:'other-windows',count:windows.length-1});
  }));
});
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET' || new URL(event.request.url).origin!==self.location.origin)return;
  event.respondWith(caches.open(CACHE).then(async cache=>await cache.match(event.request) || fetch(event.request)));
});
